DO $qa$
DECLARE m uuid:=gen_random_uuid(); c uuid:=gen_random_uuid(); c2 uuid:=gen_random_uuid(); disabled uuid:=gen_random_uuid();
 b1 uuid:=gen_random_uuid(); b2 uuid:=gen_random_uuid(); global_id bigint; screen_id bigint; role_id bigint; mobile_id bigint; next_id bigint; stale_id bigint; restored bigint; r jsonb; denied boolean; passes int:=0;
BEGIN
 BEGIN
 INSERT INTO public.ff_branches(id,code,name) VALUES(b1,'qa-'||b1,'QA one'),(b2,'qa-'||b2,'QA two');
 INSERT INTO auth.users(id) VALUES(m),(c),(c2),(disabled);
 INSERT INTO public.ff_profiles(user_id,display_name,role,active) VALUES(m,'QA manager','manager',true),(c,'QA cashier','cashier',true),(c2,'QA cashier 2','cashier',true),(disabled,'QA disabled','cashier',false) ON CONFLICT(user_id) DO UPDATE SET role=excluded.role,active=excluded.active;
 INSERT INTO public.ff_user_branches(user_id,branch_id) VALUES(c,b1),(c2,b2),(disabled,b1);
 PERFORM set_config('request.jwt.claim.sub',m::text,true); SET LOCAL ROLE authenticated;
 global_id:=public.ff_a07_named_design('all','all',b1,'all','D01','','labels','global','',NULL,'{}');
 PERFORM public.ff_ui_publish(global_id);
 screen_id:=public.ff_a07_named_design('cashier','all',b1,'all','D03','','labels','screen','',NULL,'{"radius":"round"}');
 role_id:=public.ff_a07_named_design('all','cashier',b1,'all','D02','','labels','role','',NULL,'{}');
 PERFORM public.ff_ui_publish(screen_id);PERFORM public.ff_ui_publish(role_id);
 mobile_id:=public.ff_a07_named_design('cashier','cashier',b1,'mobile','D09','','labels','mobile','',NULL,'{"font":"tahoma","logoSize":"large"}');
 IF (SELECT id FROM public.ff_a07_manager_source('cashier','cashier',b1,'mobile'))<>screen_id THEN RAISE EXCEPTION 'Draft leaked into source';END IF; passes:=passes+1;
 IF (SELECT count(*) FROM public.ff_ui_trial_accounts(mobile_id))<>1 THEN RAISE EXCEPTION 'Trial account scope';END IF; passes:=passes+1;
 PERFORM public.ff_ui_control_trial(mobile_id,ARRAY[c],1);
 denied:=false;BEGIN PERFORM public.ff_ui_control_trial(mobile_id,ARRAY[c2],1);EXCEPTION WHEN OTHERS THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'Foreign trial';END IF;passes:=passes+1;
 denied:=false;BEGIN PERFORM public.ff_a07_named_design('cashier','cashier',b1,'mobile','D09','','labels','unsafe','',NULL,'{"radius":"url(evil)"}');EXCEPTION WHEN OTHERS THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Unsafe style';END IF;passes:=passes+1;
 RESET ROLE;
 PERFORM set_config('request.jwt.claim.sub',c::text,true);SET LOCAL ROLE authenticated;
 r:=public.ff_a07_effective_designs(NULL,'mobile');
 IF (r->'cashier'->>'id')::bigint<>mobile_id OR r->'cashier'->'style_config'->>'font'<>'tahoma' OR (r->'driver'->>'id')::bigint<>role_id THEN RAISE EXCEPTION 'Trial or screen leakage %',r;END IF;passes:=passes+1;
 r:=public.ff_a07_effective_designs(b1,'desktop');
 IF (r->'cashier'->>'id')::bigint<>screen_id OR (r->'orders'->>'id')::bigint<>role_id THEN RAISE EXCEPTION 'Screen tie priority';END IF;passes:=passes+1;
 denied:=false;BEGIN PERFORM public.ff_a07_effective_designs(b2,'mobile');EXCEPTION WHEN SQLSTATE '42501' THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Foreign branch';END IF;passes:=passes+1;
 denied:=false;BEGIN PERFORM public.ff_ui_publish(mobile_id);EXCEPTION WHEN SQLSTATE '42501' THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Nonmanager publish';END IF;passes:=passes+1;
 denied:=false;BEGIN PERFORM public.ff_a07_named_design('cashier','cashier',b1,'mobile','D01','','labels','bad','',NULL,'{}');EXCEPTION WHEN SQLSTATE '42501' THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Nonmanager draft';END IF;passes:=passes+1;
 denied:=false;BEGIN PERFORM public.ff_a07_manager_source('cashier','cashier',b1,'mobile');EXCEPTION WHEN SQLSTATE '42501' THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Nonmanager source';END IF;passes:=passes+1;
 RESET ROLE;
 PERFORM set_config('request.jwt.claim.sub',m::text,true);SET LOCAL ROLE authenticated;
 PERFORM public.ff_ui_control_trial(mobile_id,ARRAY[c],0);
 RESET ROLE;PERFORM set_config('request.jwt.claim.sub',c::text,true);SET LOCAL ROLE authenticated;
 r:=public.ff_a07_effective_designs(b1,'mobile');IF (r->'cashier'->>'id')::bigint<>screen_id THEN RAISE EXCEPTION 'Trial stop';END IF;passes:=passes+1;
 RESET ROLE;PERFORM set_config('request.jwt.claim.sub',m::text,true);SET LOCAL ROLE authenticated;
 PERFORM public.ff_ui_publish(mobile_id);
 next_id:=public.ff_a07_named_design('cashier','cashier',b1,'mobile','D16','','labels','next','',NULL,'{"radius":"square"}');
 stale_id:=public.ff_a07_named_design('cashier','cashier',b1,'mobile','D15','','labels','stale','',NULL,'{}');
 PERFORM public.ff_ui_publish(next_id);
 denied:=false;BEGIN PERFORM public.ff_ui_publish(stale_id);EXCEPTION WHEN OTHERS THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Stale publish';END IF;passes:=passes+1;
 restored:=public.ff_ui_rollback(next_id);
 IF (SELECT id FROM public.ff_a07_manager_source('cashier','cashier',b1,'mobile'))<>restored THEN RAISE EXCEPTION 'Rollback source';END IF;passes:=passes+1;
 RESET ROLE;PERFORM set_config('request.jwt.claim.sub',c::text,true);SET LOCAL ROLE authenticated;
 r:=public.ff_a07_effective_designs(b1,'mobile');
 IF r->'cashier'->>'pack'<>'D09' OR r->'cashier'->'style_config'->>'logoSize'<>'large' OR (r->'dashboard'->>'id')::bigint<>role_id THEN RAISE EXCEPTION 'Rollback style/scope';END IF;passes:=passes+1;
 IF (SELECT id FROM public.ff_ui_effective(b1,'mobile'))<>role_id THEN RAISE EXCEPTION 'Legacy dashboard';END IF;passes:=passes+1;
 RESET ROLE;PERFORM set_config('request.jwt.claim.sub',c2::text,true);SET LOCAL ROLE authenticated;
 r:=public.ff_a07_effective_designs(b2,'mobile');
 IF (r->'cashier'->>'id')::bigint IN (screen_id,mobile_id,restored,role_id,global_id) THEN RAISE EXCEPTION 'Cross branch config';END IF;passes:=passes+1;
 RESET ROLE;PERFORM set_config('request.jwt.claim.sub',disabled::text,true);SET LOCAL ROLE authenticated;
 denied:=false;BEGIN PERFORM public.ff_a07_effective_designs(b1,'mobile');EXCEPTION WHEN SQLSTATE '42501' THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Disabled account';END IF;passes:=passes+1;
 RESET ROLE;
 IF has_function_privilege('anon','public.ff_a07_effective_designs(uuid,text)','EXECUTE') OR has_function_privilege('authenticated','ff_private.a07_resolve(text,text,uuid,text,uuid)','EXECUTE') THEN RAISE EXCEPTION 'Unsafe grants';END IF;passes:=passes+1;
 IF (SELECT count(*) FROM public.ff_audit_log WHERE actor_id=m AND action IN ('a07_design_trial_start','a07_design_trial_stop'))<>2 OR NOT EXISTS(SELECT 1 FROM public.ff_audit_log WHERE actor_id=m AND action='a07_design_publish' AND entity_id=restored::text) THEN RAISE EXCEPTION 'Lifecycle audit missing';END IF;passes:=passes+1;
 RAISE EXCEPTION 'QA rollback' USING ERRCODE='ZQ001';
 EXCEPTION WHEN SQLSTATE 'ZQ001' THEN NULL; END;
 IF passes<>19 OR EXISTS(SELECT 1 FROM public.ff_ui_versions WHERE actor_id=m) OR EXISTS(SELECT 1 FROM public.ff_branches WHERE id IN(b1,b2)) THEN RAISE EXCEPTION 'QA incomplete: %',passes; END IF;
END $qa$;
SELECT 'PASS A07: 19 isolated scope, lifecycle, audit and security assertions; rollback' result;
